select * from (
select 'main' as __text, 'main' as __value
union
select distinct ResourceAttributes['alasio.branch'], ResourceAttributes['alasio.branch']
from otel.traces where SpanName = 'alasio.turn' and ServiceName = 'alasio' and ResourceAttributes['alasio.branch'] is not null and Timestamp >= epoch_ms(${__from}) and Timestamp < epoch_ms(${__to})
union
select distinct substr(Attributes['k8s.namespace.name'], length('alasio-branch-') + 1), substr(Attributes['k8s.namespace.name'], length('alasio-branch-') + 1)
from otel.metrics_histogram where MetricName = 'alasio.binder.bind.duration' and Attributes['alasio.binder.pool'] like 'harness-%' and Attributes['k8s.namespace.name'] like 'alasio-branch-%' and ServiceName = 'alasio-sandbox-gateway' and TimeUnix >= epoch_ms(${__from}) and TimeUnix < epoch_ms(${__to})
union
select distinct substr(Attributes['k8s.namespace.name'], length('alasio-branch-') + 1), substr(Attributes['k8s.namespace.name'], length('alasio-branch-') + 1)
from otel.metrics_sum where MetricName = 'alasio.gateway.releases' and Attributes['alasio.binder.pool'] like 'harness-%' and Attributes['k8s.namespace.name'] like 'alasio-branch-%' and ServiceName = 'alasio-sandbox-gateway' and TimeUnix >= epoch_ms(${__from}) and TimeUnix < epoch_ms(${__to})
) order by __value <> 'main', __value

select coalesce(sum(added_count), 0) as binds
from (
select TimeUnix, Attributes, Sum - coalesce(lag(Sum) over series, 0) as added_sum, Count::bigint - coalesce(lag(Count::bigint) over series, 0) as added_count
from otel.metrics_histogram where MetricName = 'alasio.binder.bind.duration' and ServiceName = 'alasio-sandbox-gateway' and Attributes['alasio.binder.pool'] like 'harness-%' and Attributes['k8s.namespace.name'] = if(${branch:sqlstring} = 'main', 'alasio', 'alasio-branch-' || ${branch:sqlstring}) and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added_count > 0

select sum(added_sum) / sum(added_count) as seconds
from (
select TimeUnix, Attributes, Sum - coalesce(lag(Sum) over series, 0) as added_sum, Count::bigint - coalesce(lag(Count::bigint) over series, 0) as added_count
from otel.metrics_histogram where MetricName = 'alasio.binder.bind.duration' and ServiceName = 'alasio-sandbox-gateway' and Attributes['alasio.binder.pool'] like 'harness-%' and Attributes['k8s.namespace.name'] = if(${branch:sqlstring} = 'main', 'alasio', 'alasio-branch-' || ${branch:sqlstring}) and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added_count > 0

select coalesce(sum(added), 0) as lost
from (
select TimeUnix, Attributes, Value - coalesce(lag(Value) over series, 0) as added
from otel.metrics_sum where MetricName = 'alasio.gateway.releases' and ServiceName = 'alasio-sandbox-gateway' and Attributes['alasio.binder.pool'] like 'harness-%' and Attributes['k8s.namespace.name'] = if(${branch:sqlstring} = 'main', 'alasio', 'alasio-branch-' || ${branch:sqlstring}) and Attributes['alasio.gateway.release.reason'] in ('lost', 'deleted', 'broken') and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added > 0

select coalesce(sum(added), 0) as turns
from (
select TimeUnix, Attributes, Value - coalesce(lag(Value) over series, 0) as added
from otel.metrics_sum where MetricName = 'alasio.harness.recoveries' and ServiceName = 'alasio' and coalesce(ResourceAttributes['alasio.branch'], 'main') = ${branch:sqlstring} and Attributes['alasio.harness.recovery.outcome'] = 'staged' and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added > 0

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, Attributes['alasio.harness.recovery.outcome'] || ', ' || Attributes['alasio.harness.recovery.by'] as recovery, sum(added) as turns
from (
select TimeUnix, Attributes, Value - coalesce(lag(Value) over series, 0) as added
from otel.metrics_sum where MetricName = 'alasio.harness.recoveries' and ServiceName = 'alasio' and coalesce(ResourceAttributes['alasio.branch'], 'main') = ${branch:sqlstring} and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added > 0
group by all order by 1

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, Attributes['alasio.harness'] as harness, sum(added_sum) / sum(added_count) as seconds
from (
select TimeUnix, Attributes, Sum - coalesce(lag(Sum) over series, 0) as added_sum, Count::bigint - coalesce(lag(Count::bigint) over series, 0) as added_count
from otel.metrics_histogram where MetricName = 'alasio.turn.first_output' and ServiceName = 'alasio' and coalesce(ResourceAttributes['alasio.branch'], 'main') = ${branch:sqlstring} and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added_count > 0
group by all order by 1
